import { Box, Grid, Container, Typography } from "@mui/material";
import React from "react";
import CaseStudy from "../../home/CaseStudy";
import "../../../../styles/animation.css";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError, toastSuccess } from "src/utils/utils";
import { useState } from "react";
import { useEffect } from "react";
import FallbackSpinner from "src/@core/components/spinner";

const caseStudies = [1, 2, 3];
const CaseStudies = () => {
  const [successStoriesData, setSuccessStoriesData] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchSuccessStoriesData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.SUCCESS_STORIES.list)
      .then((response) => {
        const responseData = response.data.data;
        const activeData = responseData.filter(
          (item) => item.status === "active"
        );
        setSuccessStoriesData(activeData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchSuccessStoriesData();
  }, []);

  if (loading) return <FallbackSpinner />;
  return (
    <Box>
      <Container
        maxWidth={"xl"}
        sx={{
          px: { xs: 5, sm: 10, lg: 15, xl: 20 },
        }}
      >
        <Grid container rowGap={{ xs: 5, md: 12 }}>
          <Grid
            item
            xs={12}
            sx={{
              display: "flex",
              flexDirection: "column",
              gap: 3,
              alignItems: "center",
            }}
          >
            <Typography
              sx={{
                fontSize: {
                  xs: "26px",
                  sm: "36px",
                  md: "46px",
                  lg: "56px",
                },
                fontWeight: 500,
                lineHeight: {
                  xs: "40px",
                  sm: "50px",
                  md: "60px",
                  lg: "70px",
                },
                color: "#201D28",
                textAlign: "center",
              }}
              className="fade-in-up-whoweare"
            >
              Success Stories
            </Typography>
            <Typography
              sx={{
                fontSize: { lg: "18px" },
                fontWeight: 500,
                lineHeight: { lg: "30px" },
                color: "#646271",
                textAlign: "center",
              }}
              className="fade-in-up-whoweare"
            >
              Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do
              eiusmod tempor incididunt ut labore
            </Typography>
          </Grid>
          <Grid item container columnSpacing={5} xs={12} sx={{ mt: { lg: 5 } }}>
            <Grid item xs={12} md={6}>
              <Typography
                sx={{
                  fontSize: {
                    xs: "26px",
                    sm: "36px",
                    md: "46px",
                    lg: "56px",
                  },
                  fontWeight: 500,
                  lineHeight: {
                    xs: "40px",
                    sm: "50px",
                    md: "60px",
                    lg: "70px",
                  },
                  color: "#201D28",
                }}
                className="fade-in-up-whoweare"
              >
                Client Success: Case Studies.
              </Typography>
            </Grid>
            <Grid
              item
              xs={12}
              md={6}
              sx={{ display: "flex", alignItems: "center" }}
            >
              <Typography
                sx={{
                  fontSize: { lg: "18px" },
                  fontWeight: 500,
                  lineHeight: { lg: "30px" },
                  color: "#646271",
                }}
                className="fade-in-up-whoweare"
              >
                Lorem ipsum dolor sit amet, consectetur adipiscing elit.
                Suspendisse varius enim in eros elementum tristique. Duis
                cursus, mi quis viverra ornare, Lorem ipsum dolor sit amet,
                consectetur adipiscing elit.
              </Typography>
            </Grid>
          </Grid>
          <Grid
            item
            xs={12}
            sx={{ display: "flex", flexDirection: "column", gap: 12 }}
          >
            {successStoriesData?.map((item, index) => (
              <CaseStudy key={index} index={index} successStoriesData={item} />
            ))}
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default CaseStudies;
